package diagnostic

// RuleMetadata is the versioned public contract shared by metadata commands,
// findings and generated rule pages. Returned slices are defensive copies.
type RuleMetadata struct {
	RuleID        string   `json:"ruleId"`
	Component     string   `json:"component"`
	Prerequisites []string `json:"prerequisites"`
	Severity      Severity `json:"severity"`
	Title         string   `json:"title"`
	Evidence      string   `json:"evidence"`
	Explanation   string   `json:"explanation"`
	ManualSteps   []string `json:"manualSteps"`
	Verify        string   `json:"verify"`
	Caveats       []string `json:"caveats"`
	Docs          string   `json:"docs"`
}
type RegistryDocument struct {
	SchemaVersion int            `json:"schemaVersion"`
	Rules         []RuleMetadata `json:"rules"`
}

var builtinRules []builtinRule

