func BuiltinMetadata() []RuleMetadata {
	result := make([]RuleMetadata, 0, len(builtinRules))
	for _, rule := range builtinRules {
		result = append(result, copyMetadata(rule.metadata))
	}
	return result
}
func LookupRule(id string) (RuleMetadata, bool) {
	for _, rule := range builtinRules {
		if rule.ID() == id {
			return copyMetadata(rule.metadata), true
		}
	}
	return RuleMetadata{}, false
}
func copyMetadata(m RuleMetadata) RuleMetadata {
	m.Prerequisites = append([]string(nil), m.Prerequisites...)
	m.ManualSteps = append([]string(nil), m.ManualSteps...)
	m.Caveats = append([]string(nil), m.Caveats...)
	return m
}
